"""Manifest side of the harvest: which arXiv ids are already known, and the entries a
harvest appends to its generated manifest (WP18 §2, §4)."""

from __future__ import annotations

import re
from collections.abc import Iterable
from pathlib import Path
from typing import Any

import yaml

from kbase.harvest.schemas import ArxivEntry, HarvestQuery

_ARXIV_URL_RE = re.compile(r"arxiv\.org/(?:abs|pdf|html)/(?P<id>[^\s?#]+?)(?:v\d+)?(?:\.pdf)?$")
_HEADER = (
    "# Generated by `kbase harvest` (WP18), then read by `kbase ingest`. Paths are relative\n"
    "# to AGX_PATHS_DOCUMENTS_DIR. Removing an entry is fine; edit the harvest profiles\n"
    "# (configs/harvest/) to change what gets harvested.\n"
)


def safe_id(arxiv_id: str) -> str:
    """File-name-safe id: old-style `math/0501001` → `math_0501001`."""
    return arxiv_id.replace("/", "_")


def doc_key(arxiv_id: str) -> str:
    return "arxiv-" + arxiv_id.replace("/", "-")


def markdown_path(arxiv_id: str, md_dir: str) -> str:
    return f"{md_dir.rstrip('/')}/{safe_id(arxiv_id)}.md"


def _load_documents(path: Path) -> list[dict[str, Any]]:
    if not path.is_file():
        return []
    raw = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    documents = raw.get("documents") or []
    return [d for d in documents if isinstance(d, dict)]


def known_arxiv_ids(manifests: Iterable[Path]) -> set[str]:
    """arXiv ids (no version) any manifest already points at, through `source_url`."""
    known: set[str] = set()
    for manifest in manifests:
        for document in _load_documents(manifest):
            match = _ARXIV_URL_RE.search(str(document.get("source_url") or ""))
            if match:
                known.add(match.group("id"))
    return known


def build_entry(entry: ArxivEntry, query: HarvestQuery, *, md_dir: str) -> dict[str, Any]:
    document: dict[str, Any] = {
        "doc_key": doc_key(entry.arxiv_id),
        "path": markdown_path(entry.arxiv_id, md_dir),
        "title": entry.title,
        "authors": entry.authors,
        "year": entry.published.year,
        "doc_type": "research_paper",
        "topic": query.topic,
    }
    if query.asset_class:
        document["asset_class"] = query.asset_class
    document["source_url"] = f"https://arxiv.org/abs/{entry.arxiv_id}v{entry.version}"
    document["license"] = "arXiv preprint; terms on the abs page"
    return document


def append_entries(manifest: Path, entries: list[dict[str, Any]]) -> int:
    """Appends entries whose doc_key is not there yet; returns how many were added."""
    documents = _load_documents(manifest)
    present = {d.get("doc_key") for d in documents}
    added = [e for e in entries if e["doc_key"] not in present]
    if not added:
        return 0
    manifest.parent.mkdir(parents=True, exist_ok=True)
    body = yaml.safe_dump(
        {"documents": documents + added}, sort_keys=False, allow_unicode=True, width=100
    )
    manifest.write_text(_HEADER + "\n" + body, encoding="utf-8")
    return len(added)
